update wine_archetypes set description = $d$Sherry aged oxidatively, without flor, for years in the solera: amber to brown, with walnut, hazelnut and toffee, a full, rounded body and 17–20 % alcohol, yet bone dry. The dryness separates it from cream sherry and tawny Port.$d$ where name = 'A typical Oloroso';

-- 5. Removals, only once nothing references them.
do $refs$
begin
  if exists (select 1 from wine_archetype_aromas where term_id in ('87a25700-91d3-4ffd-a313-364756bd3610', '30bcee78-6a8c-4283-a11b-cb865be4dc0d', 'ac4f75b9-70e9-4aa9-8fc1-f0fc28ae7edc', '7e602a5e-9602-459b-af84-6a413b6a173a', '5d0ffa77-f3ad-4b18-8373-0a023783481e')) then raise exception 'removal: a typical wine still links a removed term'; end if;
  if exists (select 1 from wset_note_aromas where term_id in ('87a25700-91d3-4ffd-a313-364756bd3610', '30bcee78-6a8c-4283-a11b-cb865be4dc0d', 'ac4f75b9-70e9-4aa9-8fc1-f0fc28ae7edc', '7e602a5e-9602-459b-af84-6a413b6a173a', '5d0ffa77-f3ad-4b18-8373-0a023783481e')) then raise exception 'removal: a saved note still holds a removed term'; end if;
end $refs$;
delete from wset_aroma_terms where id = '87a25700-91d3-4ffd-a313-364756bd3610'; -- dried fruit (Fruit ripeness)
delete from wset_aroma_terms where id = '30bcee78-6a8c-4283-a11b-cb865be4dc0d'; -- cooked fruit (Fruit ripeness)
delete from wset_aroma_terms where id = 'ac4f75b9-70e9-4aa9-8fc1-f0fc28ae7edc'; -- kerosene (White wine)
delete from wset_aroma_terms where id = '7e602a5e-9602-459b-af84-6a413b6a173a'; -- graham cracker (Yeast)
delete from wset_aroma_terms where id = '5d0ffa77-f3ad-4b18-8373-0a023783481e'; -- cooked red plum (Red wine)

-- Post-state.
do $post$
begin
  if not ((select count(*) from wset_aroma_terms) = 150) then raise exception 'post-state: expected 150 aroma terms'; end if;
  if not ((select count(*) from wset_aroma_terms where origin = 'PRIMARY') = 73 and (select count(*) from wset_aroma_terms where origin = 'SECONDARY') = 24 and (select count(*) from wset_aroma_terms where origin = 'TERTIARY') = 53) then raise exception 'post-state: origin split is not 73/24/53'; end if;
  if not ((select count(distinct group_name) from wset_aroma_terms) = 18) then raise exception 'post-state: expected 18 groups'; end if;
  if not ((select array_agg(distinct family::text order by family::text) from wset_aroma_terms) = array['FLORAL','FRUIT','OTHER','SPICE','VEGETAL_OAK']) then raise exception 'post-state: the five families changed'; end if;
  if not ((select count(distinct sort_order) from wset_aroma_terms) = 150 and (select max(sort_order) from wset_aroma_terms) = 156) then raise exception 'post-state: sort_order is not unique up to 156'; end if;
